   785  int
   786  getnum (int *pnum, char *arg, char **endp)
   787  {
   788    char *p;
   789    unsigned long x = strtoul (arg, &p, 10);
   790    if (*p && !isspace (*p))
   791      {
   792        terror (_("not a number (stopped near %s)"), p);
   793        return 1;
   794      }
   795    while (*p && isspace (*p))
   796      p++;
   797    if (endp)
   798      *endp = p;
   799    else if (*p)
   800      {
   801        terror (_("not a number (stopped near %s)"), p);
   802        return 1;
   803      }
   804    *pnum = x;
   805    return 0;
   806  }
